function parse(s) { try { return JSON.parse(s); } catch (e) { return null; } }

var raw = parse(data.context) || [];
// --query with a projection returns a flat list; tolerate the un-projected
// Reservations shape too so a hand-edited command still works.
var list = [];
if (raw.Reservations) {
  for (var r = 0; r < raw.Reservations.length; r++) {
    list = list.concat(raw.Reservations[r].Instances || []);
  }
} else { list = raw; }

function find(id) {
  for (var i = 0; i < list.length; i++) { if (list[i].InstanceId === id) { return list[i]; } }
  return null;
}
function sgIds(inst) {
  if (!inst) { return []; }
  var g = inst.SGs || inst.SecurityGroups || [];
  var out = [];
  for (var i = 0; i < g.length; i++) { out.push(typeof g[i] === 'string' ? g[i] : g[i].GroupId); }
  return out;
}

var db = find(data.db_instance_id);
var client = find(data.client_instance_id);
var dbSgs = sgIds(db);

({
  found_db: !!db,
  found_client: !!client,
  db_state: db ? (db.State || db.StateName || '') : '',
  db_ip: db ? (db.PrivateIp || db.PrivateIpAddress || '') : '',
  db_subnet: db ? (db.SubnetId || '') : '',
  db_sgs: dbSgs,
  // Space-separated for the --group-ids argument; empty string would make the
  // CLI list every group in the account, so a sentinel keeps it scoped to none.
  db_sgs_arg: dbSgs.length ? dbSgs.join(' ') : 'sg-none',
  db_subnet_arg: db && db.SubnetId ? db.SubnetId : 'subnet-none',
  // Absent instance profile is the EC2 stand-in for "IAM auth failure": with no
  // role the host cannot read its database credential out of Secrets Manager.
  db_instance_profile: db ? (db.Profile || '') : '',
  client_ip: client ? (client.PrivateIp || client.PrivateIpAddress || '') : '',
  client_sgs: sgIds(client)
})

var lead = (data.lead_minutes || 15) * 60000;
var raw = data.override || data.starts_at || '';
var anchor = raw ? new Date(raw) : new Date();
if (isNaN(anchor.getTime())) { anchor = new Date(); }
var now = new Date();
var incidentStart = new Date(anchor.getTime() - lead);
var incidentEnd = new Date(Math.min(now.getTime(), anchor.getTime() + 30 * 60000));
function iso(d) { return d.toISOString().replace(/\.\d{3}Z$/, 'Z'); }
({
  anchor: iso(anchor),
  incident_start: iso(incidentStart),
  incident_end: iso(incidentEnd),
  searched: 'incident ' + iso(incidentStart) + ' to ' + iso(incidentEnd)
})

// to_json renders a STRING task output as a JSON string, but an OBJECT output
// (observability.logs) as a JSON object — so by the time this runs, some inputs
// are already decoded. JSON.parse on an object stringifies it to
// "[object Object]" and throws, which silently reported a query that ran fine
// as "did not run". Accept both shapes.
function parse(s) {
  if (s === null || s === undefined) { return null; }
  if (typeof s === 'object') { return s; }
  try { return JSON.parse(s); } catch (e) { return null; }
}

// A task that ran and one that was skipped by failure_policy=continue both
// arrive as a value; only a non-empty parse means it actually produced data.
// Conflating "query failed" with "no rows" is what turns a broken check into a
// confident wrong verdict, so every fact below carries its own *_ran flag.
function txt(s) { return (s === null || s === undefined) ? '' : String(s); }

var ids = data.ids || {};
var facts = {};
var notes = [];

// ---- client vantage -------------------------------------------------------
var dns = txt(data.dns);
facts.dns_ran = dns.length > 0;
var addresses = [];
if (facts.dns_ran) {
  var lines = dns.split('\n');
  for (var i = 0; i < lines.length; i++) {
    var m = lines[i].match(/^\s*([0-9a-fA-F:.]+)\s+\S/);
    if (m) { addresses.push(m[1]); }
  }
}
facts.dns_failed = facts.dns_ran && (dns.indexOf('NXDOMAIN') >= 0 || addresses.length === 0);
facts.dns_ok = facts.dns_ran && !facts.dns_failed;

var tcp = txt(data.tcp);
facts.tcp_ran = tcp.length > 0;
facts.tcp_open = tcp.indexOf('TCP_OPEN') >= 0;
facts.tcp_timeout = tcp.indexOf('TCP_TIMEOUT') >= 0;
facts.tcp_refused = tcp.indexOf('TCP_REFUSED') >= 0;
facts.client_vantage = facts.dns_ran || facts.tcp_ran;

// ---- security group evaluation -------------------------------------------
// Deliberately evaluating RULES rather than trusting the probe: this is the
// only step that can say WHY the path is closed.
function ipToInt(ip) {
  var p = ip.split('.');
  if (p.length !== 4) { return null; }
  var n = 0;
  for (var i = 0; i < 4; i++) {
    var o = parseInt(p[i], 10);
    if (isNaN(o) || o < 0 || o > 255) { return null; }
    n = n * 256 + o;
  }
  return n;
}
function inCidr(ip, cidr) {
  var parts = cidr.split('/');
  if (parts.length !== 2) { return false; }
  var base = ipToInt(parts[0]);
  var addr = ipToInt(ip);
  if (base === null || addr === null) { return false; }
  var bits = parseInt(parts[1], 10);
  if (isNaN(bits) || bits < 0 || bits > 32) { return false; }
  if (bits === 0) { return true; }
  var mask = (-1 << (32 - bits)) >>> 0;
  return ((base & mask) >>> 0) === ((addr & mask) >>> 0);
}

var port = parseInt(data.port, 10);
var sgDoc = parse(data.sg_rules);
var groups = sgDoc ? (sgDoc.SecurityGroups || sgDoc) : null;
var clientIp = ids.client_ip || '';
var clientSgs = ids.client_sgs || [];
var matched = [];

facts.sg_evaluated = !!(groups && groups.length && (clientIp || clientSgs.length));
if (facts.sg_evaluated) {
  for (var g = 0; g < groups.length; g++) {
    var perms = groups[g].IpPermissions || [];
    for (var p = 0; p < perms.length; p++) {
      var perm = perms[p];
      var proto = String(perm.IpProtocol);
      if (proto !== 'tcp' && proto !== '-1') { continue; }
      // -1 means all protocols and all ports; FromPort/ToPort are absent.
      var covers = proto === '-1' ||
                   (perm.FromPort <= port && port <= perm.ToPort);
      if (!covers) { continue; }
      var ranges = perm.IpRanges || [];
      for (var r = 0; r < ranges.length; r++) {
        if (clientIp && inCidr(clientIp, ranges[r].CidrIp)) {
          matched.push(groups[g].GroupId + ' allows ' + ranges[r].CidrIp);
        }
      }
      var pairs = perm.UserIdGroupPairs || [];
      for (var q = 0; q < pairs.length; q++) {
        for (var c = 0; c < clientSgs.length; c++) {
          if (pairs[q].GroupId === clientSgs[c]) {
            matched.push(groups[g].GroupId + ' allows sg ' + pairs[q].GroupId);
          }
        }
      }
    }
  }
}
facts.sg_allows_client = facts.sg_evaluated && matched.length > 0;
facts.sg_denies_client = facts.sg_evaluated && matched.length === 0;
if (!facts.sg_evaluated) {
  notes.push('security group rules were not evaluated (missing rules or client identity)');
}

// ---- database side --------------------------------------------------------
var avail = parse(data.availability);
facts.db_query_ran = !!(avail && avail.length);
facts.db_reachable = facts.db_query_ran;

var cap = parse(data.capacity);
var capRow = (cap && cap.length) ? cap[0] : null;
facts.capacity_ran = !!capRow;
var headroom = null;
if (capRow) {
  headroom = Number(capRow.headroom_for_normal_users);
  if (isNaN(headroom)) { headroom = null; }
}
facts.capacity_exhausted = headroom !== null && headroom <= 0;

// ---- authentication -------------------------------------------------------
var authDoc = parse(data.auth_log);
// A CloudWatch Insights failure is a hard error, not an empty result set, so
// the presence of metadata is what distinguishes "ran, found nothing" from
// "never ran". Treating those as the same produced a false critical once.
var authRan = !!(authDoc && authDoc.metadata);
// observability.logs returns its rows under "logs"; "data" is the shape other
// tasks use, kept as a fallback so a provider change does not silently zero it.
var authRows = [];
if (authDoc) { authRows = authDoc.logs || authDoc.data || []; }
if (!authRan && authRows.length) { authRan = true; }
facts.auth_log_ran = authRan;
facts.auth_errors_found = authRan && authRows.length > 0;
if (!authRan) { notes.push('database log query for authentication failures did not run'); }

facts.server_side_healthy =
  facts.db_reachable && facts.capacity_ran && !facts.capacity_exhausted &&
  !facts.auth_errors_found &&
  (!facts.sg_evaluated || facts.sg_allows_client) &&
  (!facts.tcp_ran || facts.tcp_open);

// ---- ordered cause ranking (data, from the pack) --------------------------
var ranking = data.ranking || [];
var conclusion = null;
for (var i = 0; i < ranking.length; i++) {
  var rule = ranking[i];
  var all = rule.all || [];
  var ok = all.length > 0;
  for (var j = 0; j < all.length; j++) {
    if (!facts[all[j]]) { ok = false; break; }
  }
  if (ok) { conclusion = rule; break; }
}
if (!conclusion) {
  conclusion = {
    id: 'no_fault_found',
    verdict: 'info',
    cause: 'No check produced a failing signal',
    remediation: 'Nothing in the collected evidence explains a connection failure. Confirm the incident window is right, then look at the application side.'
  };
}

({
  verdict: conclusion.verdict,
  likely_cause: conclusion.cause,
  matched_rule: conclusion.id,
  remediation: conclusion.remediation,
  facts: facts,
  evidence: {
    dns_answer: addresses,
    dns_raw: dns.slice(0, 400),
    tcp_result: tcp.replace(/\s+$/, ''),
    security_group_matches: matched,
    db_security_groups: ids.db_sgs || [],
    client_ip: clientIp,
    client_security_groups: clientSgs,
    db_instance_profile: ids.db_instance_profile || '(none)',
    connection_headroom: headroom,
    capacity: capRow,
    top_clients: parse(data.clients) || [],
    auth_failure_count: authRows.length,
    auth_samples: authRows.slice(0, 5)
  },
  checks_ran: {
    dns: facts.dns_ran,
    tcp: facts.tcp_ran,
    security_groups: facts.sg_evaluated,
    db_availability: facts.db_query_ran,
    capacity: facts.capacity_ran,
    auth_log: facts.auth_log_ran
  },
  notes: notes,
  window: data.searched || ''
})

